const express = require('express');
const todosRouter = require('../../src/routes/todos');

// テスト用のシンプルな Express アプリを組み立てる
function buildApp() {
  const app = express();
  app.use(express.json());
  app.use('/todos', todosRouter);
  return app;
}

// fetch の代わりに supertest 相当の動作を node の http モジュールで再現するため、
// ここでは jest のモックを使ってルーターを直接呼び出す形でテストする

const http = require('http');

// レスポンスを Promise で受け取るヘルパー
function request(app, method, path, body) {
  return new Promise((resolve) => {
    const server = http.createServer(app);
    server.listen(0, () => {
      const port = server.address().port;
      const options = {
        hostname: 'localhost',
        port,
        path,
        method,
        headers: { 'Content-Type': 'application/json' },
      };
      const req = http.request(options, (res) => {
        let data = '';
        res.on('data', (chunk) => { data += chunk; });
        res.on('end', () => {
          server.close();
          resolve({
            status: res.statusCode,
            body: data ? JSON.parse(data) : null,
          });
        });
      });
      if (body) req.write(JSON.stringify(body));
      req.end();
    });
  });
}

// 各テスト前にモジュールキャッシュをリセットしてインメモリ状態を初期化する
beforeEach(() => {
  jest.resetModules();
});

describe('GET /todos', () => {
  test('初期状態では空配列を返す', async () => {
    const router = require('../../src/routes/todos');
    const app = express();
    app.use(express.json());
    app.use('/todos', router);

    const res = await request(app, 'GET', '/todos');
    expect(res.status).toBe(200);
    expect(res.body).toEqual([]);
  });
});

describe('POST /todos', () => {
  test('title を渡すと 201 で TODO を返す', async () => {
    const router = require('../../src/routes/todos');
    const app = express();
    app.use(express.json());
    app.use('/todos', router);

    const res = await request(app, 'POST', '/todos', { title: 'テスト用タスク' });
    expect(res.status).toBe(201);
    expect(res.body.title).toBe('テスト用タスク');
    expect(res.body.completed).toBe(false);
  });

  test('title が空の場合は 400 を返す', async () => {
    const router = require('../../src/routes/todos');
    const app = express();
    app.use(express.json());
    app.use('/todos', router);

    const res = await request(app, 'POST', '/todos', { title: '   ' });
    expect(res.status).toBe(400);
    expect(res.body).toHaveProperty('error');
  });
});

